try:
    print('>>> f = map')
    print('>>> x = frozenset()')
    print('>>> y = 3')
    print('>>> f(x, y)')
    f = map
    x = frozenset()
    y = 3
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
